'use strict';
const {esc,person,pill,toast,modal,closeModal,formField:F,selectField:S}=MRH;
let role=sessionStorage.getItem('mrh-role'),view=location.hash.slice(1)||'resumen';
const app=document.querySelector('#app');
const items=[['resumen','◫','Vista general'],['empleados','♙','Empleados'],['marcaciones','◷','Marcaciones'],['incidencias','⚑','Incidencias'],['turnos','▦','Turnos y jornadas'],['solicitudes','◇','Permisos y vacaciones'],['horas-extra','◴','Horas extra'],['preplanilla','▧','Preplanilla'],['reportes','▤','Reportes'],['dispositivos','▣','Dispositivos'],['empresa','◈','Empresa y sucursales'],['bitacora','≡','Bitácora']];
const masterItems=[['global','◫','Vista global'],['empresas','▥','Empresas y licencias'],['sitio','◈','Editor web pública'],['consultas','◇','Solicitudes comerciales'],['bitacora','≡','Auditoría global']];
const title=()=>[...items,...masterItems].find(x=>x[0]===view)?.[2]||'Vista general';
const nav=()=>role==='master'?masterItems:items;
function login(){app.innerHTML=`<div class="demo-bar">EXPERIENCIA DE DEMOSTRACIÓN · El acceso simula roles; no autentica usuarios <a href="index.html">Volver a la web oficial</a></div><main class="login-page"><section class="login-story"><div class="eyebrow" style="color:#79b6ff">EL ESPACIO DE TU EMPRESA</div><h1>Tu equipo, conectado.<br>Tu operación, en orden.</h1><p>Una sola vista para entender cada jornada, acompañar a tu personal y tomar decisiones con claridad.</p><div style="border-top:1px solid #ffffff22;margin-top:35px;padding-top:30px"><span class="pill" style="background:#173f50;color:#79d9bd">● Administración, sin marcación web</span><p style="font-size:12px;margin-top:20px">La asistencia se registra únicamente en las terminales instaladas de tu empresa.</p></div></section><section class="login-form-wrap"><div class="login-form"><a href="index.html"><img class="brand" src="assets/logo.svg" alt="MarkaRH"></a><h2>Bienvenido a tu espacio.</h2><p>Explora el panel con una sesión de demostración.</p><div class="login-role"><button class="active" data-role="company">Administrador de empresa</button><button data-role="master">Maestro MarkaRH</button></div><div class="notice" id="role-description">Gestiona empleados, horarios y reportes de Multiservicios Central. Todos los datos son ficticios.</div><label class="checkbox"><input type="checkbox" id="demo-consent"> Entiendo que este es un prototipo con datos locales y que no debo ingresar información real.</label><p class="error" id="login-error" role="alert"></p><button class="btn" style="width:100%" id="enter-demo">Entrar a la demo →</button><p style="font-size:10px;margin-top:22px">El producto final tendrá autenticación segura, permisos por empresa y MFA obligatorio para Maestro.</p></div></section></main>`;let selectedRole='company';app.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{selectedRole=b.dataset.role;app.querySelectorAll('[data-role]').forEach(x=>x.classList.toggle('active',x===b));app.querySelector('#role-description').textContent=selectedRole==='master'?'Gestiona empresas y licencias, revisa solicitudes comerciales y edita el sitio público. No se accede a datos laborales de otros negocios.':'Gestiona empleados, horarios y reportes de Multiservicios Central. Todos los datos son ficticios.'});app.querySelector('#enter-demo').onclick=()=>{if(!app.querySelector('#demo-consent').checked){app.querySelector('#login-error').textContent='Confirma que entiendes el alcance de esta demostración.';return}role=selectedRole;sessionStorage.setItem('mrh-role',role);view=role==='master'?'global':'resumen';location.hash=view;MRH.audit('Acceso demo',role==='master'?'Vista Maestro':'Vista empresa');shell()}}
function shell(){if(!role)return login();if(!nav().some(x=>x[0]===view))view=nav()[0][0];app.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><a href="index.html"><img class="brand" src="assets/logo.svg" alt="MarkaRH"></a><div class="workspace-tag"><span class="avatar" style="background:#26476e;color:white">${role==='master'?'M':'MC'}</span><div>${role==='master'?'Espacio Maestro':esc(MRH.state.settings.company)}<small>${role==='master'?'Administración global':'Plan Profesional · Demo'}</small></div></div><div class="nav-label">${role==='master'?'PLATAFORMA':'ESPACIO DE TRABAJO'}</div><nav class="side-nav" aria-label="Módulos administrativos">${nav().map(([id,icon,label])=>`<a class="nav-item ${view===id?'active':''}" href="#${id}" ${view===id?'aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${icon}</span>${label}${id==='incidencias'?`<span style="margin-left:auto;font-size:9px;background:#314d71;padding:3px 5px;border-radius:4px">${MRH.state.issues.filter(i=>i.status==='Pendiente').length}</span>`:''}</a>`).join('')}</nav><div class="side-foot"><div class="side-help"><b>Un espacio para explorar.</b><br>Datos ficticios, cambios locales.<br><button data-demo-info style="background:none;color:#75b8ff;padding:7px 0 0;font-size:11px">Ver alcance de la demo →</button></div><a class="nav-item" href="index.html"><span class="nav-symbol">→</span> Ir a web oficial</a><button class="nav-item" id="switch-role"><span class="nav-symbol">⇄</span> Cambiar vista demo</button><button class="nav-item" id="logout"><span class="nav-symbol">↪</span> Cerrar sesión demo</button></div></aside><div class="app-body"><header class="topbar"><div class="row"><button class="mobile-menu" id="mobile-menu" aria-label="Abrir menú" aria-expanded="false">☰</button><div class="breadcrumb">${role==='master'?'Plataforma MarkaRH':'Mi empresa'} &nbsp; / &nbsp; <strong>${esc(title())}</strong></div></div><div class="row"><span class="pill blue">${role==='master'?'Maestro':'Empresa'} · Demo</span><button class="btn ghost small" id="notifications" aria-label="Ver notificaciones">♧</button><span class="separator"></span><span class="avatar" style="background:#e9edfa">${role==='master'?'MA':'AS'}</span><div class="profile-name">${role==='master'?'Maestro MarkaRH':'Andrea Solís'}<small>${role==='master'?'Administración global':'Administradora de empresa'}</small></div></div></header><div class="demo-bar">PROTOTIPO INTERACTIVO · Datos almacenados solo en este navegador · No es un sistema en producción</div><main class="content" id="content"></main></div></div>`;app.querySelector('#logout').onclick=()=>{sessionStorage.removeItem('mrh-role');role=null;location.hash='';login()};app.querySelector('#switch-role').onclick=()=>{role=role==='master'?'company':'master';sessionStorage.setItem('mrh-role',role);view=nav()[0][0];location.hash=view;shell()};app.querySelector('#mobile-menu').onclick=()=>{const open=app.querySelector('#sidebar').classList.toggle('open');app.querySelector('#mobile-menu').setAttribute('aria-expanded',String(open));app.querySelector('#mobile-menu').setAttribute('aria-label',open?'Cerrar menú':'Abrir menú')};app.querySelector('#notifications').onclick=notifications;render()}
function head(sub,actions=''){return `<div class="page-head"><div><h1>${esc(title())}</h1><p>${sub}</p></div><div class="row wrap">${actions}</div></div>`}
function footer(){return `<footer class="page-footer"><span>MarkaRH · ${role==='master'?'Plataforma global':esc(MRH.state.settings.company)} · Demostración</span><span>Zona horaria: Costa Rica (UTC−6)</span></footer>`}
function stat(label,value,note,icon='◫',warn=false){return `<div class="stat"><div class="stat-top">${label}<span class="icon" ${warn?'style="background:#fff5e5;color:#b68b3c"':''}>${icon}</span></div><div class="stat-value">${value}</div><small ${warn?'style="color:#b28c45"':''}>${note}</small></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">No hay resultados con estos filtros.</td></tr>`}</tbody></table></div>`}
function buttonsSave(text='Guardar'){return `<div class="modal-actions"><button class="btn secondary" type="button" data-cancel>Cancelar</button><button class="btn" type="submit">${text}</button></div>`}
function wireCancel(m){m.querySelector('[data-cancel]')?.addEventListener('click',closeModal)}
function render(){const c=document.querySelector('#content');if(!c)return;const screens={resumen:dashboard,empleados:employees,marcaciones:attendance,incidencias:issues,turnos:shifts,solicitudes:leaves,'horas-extra':overtime,preplanilla:prepay,reportes:reports,dispositivos:devices,empresa:company,bitacora:audit,global:globalDashboard,empresas:companies,sitio:cms,consultas:contacts};(screens[view]||dashboard)(c);c.insertAdjacentHTML('beforeend',footer());document.title=`${title()} · MarkaRH`}
function dashboard(c){const s=MRH.state,received=s.events.filter(e=>e.status!=='Pendiente'),present=new Set(received.filter(e=>e.action==='Entrada').map(e=>e.employee)).size,pending=s.issues.filter(i=>i.status==='Pendiente').length; c.innerHTML=head('Una vista clara de tu equipo. '+MRH.day(new Date().toISOString())+' · San José, Costa Rica',`<a class="btn secondary" href="#reportes">→ Ver reportes</a>`)+`<div class="notice">◎ &nbsp; Cobertura parcial: solo se muestran eventos recibidos en la simulación. No se infiere ausencia por falta de sincronización.</div><div class="stats">${stat('Personal activo',s.employees.filter(e=>e.active).length,'En las sucursales de la empresa','♙')}${stat('Entradas recibidas',present,'Personas con entrada · No presencia en vivo','→')}${stat('Por revisar',pending,'Incidencias pendientes de resolución','⚑',true)}${stat('Dispositivos',s.devices.length,'Última recepción visible por terminal','▣')}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h3>Una semana de jornadas</h3><small>Comparativo ilustrativo · No derivado de registros</small></div><span class="pill blue">Demo</span></div><div class="legend"><span><i></i>Entradas</span><span><i class="pale"></i>Personal planificado</span></div><div class="chart" role="img" aria-label="Gráfico ilustrativo: entradas de lunes a viernes 4, 5, 4, 5 y 4; cinco planificados cada día">${[75,92,78,88,80].map(h=>`<div class="chart-group"><div class="chart-bar" style="height:${h}%"></div><div class="chart-bar pale" style="height:95%"></div></div>`).join('')}</div><div class="chart-labels"><span>Lun</span><span>Mar</span><span>Mié</span><span>Jue</span><span>Vie</span></div></section><section class="card"><div class="card-head"><h3>Tus terminales</h3><a href="#dispositivos" style="font-size:11px;color:var(--blue)">Ver todas →</a></div>${s.devices.map(d=>`<div class="device-row"><div class="row"><span class="icon" style="width:30px;height:30px;font-size:14px">${d.platform==='Windows'?'▦':'▯'}</span><div><b>${esc(d.name)}</b><small>${esc(d.platform)} · ${esc(d.id)}</small><small>Recepción demo: ${d.id==='SJ-01'&&s.lastSync?MRH.time(s.lastSync):'Sin sincronización ejecutada'}</small></div></div>${pill(d.state)}</div>`).join('')}<div class="notice" style="margin-top:17px;font-size:10px">Los equipos desconectados pueden tener datos pendientes que aún no aparecen aquí.</div></section></div><section class="card" style="margin-bottom:22px"><div class="card-head"><div><h3>Cada detalle cuenta</h3><small>Atiende las incidencias que necesitan una decisión.</small></div><a href="#incidencias" class="btn secondary small">Revisar pendientes →</a></div>${s.issues.filter(i=>i.status==='Pendiente').slice(0,3).map(i=>`<div class="alert-row"><div class="row"><span class="icon" style="background:#fff6e8;color:#c09b55">!</span><div><b>${esc(i.title)}</b><small>${esc(MRH.employee(i.employee)?.name)} · ${esc(i.detail)}</small></div></div><button class="btn ghost small" data-issue="${esc(i.id)}">Revisar →</button></div>`).join('')||'<div class="empty">Todo al día. No hay incidencias pendientes.</div>'}</section><section class="card"><div class="card-head"><div><h3>Últimos registros recibidos</h3><small>Conservados por origen · Sin cambios silenciosos</small></div><a href="#marcaciones" style="font-size:11px;color:var(--blue)">Ver todos →</a></div>${eventsTable(received.slice(-5).reverse())}</section>`;wireIssues(c)}
function eventsTable(events,actions=true){return table(['Empleado','Fecha / hora local','Evento','Terminal','Estado',...(actions?['']:[])],events.map(e=>`<tr><td>${person(e.employee)}</td><td>${MRH.time(e.time)}<small style="display:block;font-size:9px;margin-top:5px">${MRH.day(e.time)}</small></td><td>${esc(e.action)}</td><td>${esc(e.device)}</td><td>${pill(e.status)}</td>${actions?`<td><button class="btn ghost small" data-event="${esc(e.id)}">Detalle →</button></td>`:''}</tr>`).join(''))}
function wireEvents(c){c.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>eventDetail(b.dataset.event))}
function eventDetail(id){const e=MRH.state.events.find(x=>x.id===id);modal('Detalle de la evidencia',`${person(e.employee)}<div class="grid2" style="margin-top:25px"><div class="field"><label>Evento original</label><b>${esc(e.action)}</b></div><div class="field"><label>Estado demo</label>${pill(e.status)}</div><div class="field"><label>Fecha / hora local CR</label>${MRH.day(e.time)} · ${MRH.time(e.time)}</div><div class="field"><label>Terminal de origen</label>${esc(e.device)}</div></div><div class="notice">UUID: ${esc(e.id)}<br>Confianza: hora local del navegador, sin certificación de servidor.<br>Método: PIN de demostración. Fotografía: no capturada.</div><p class="muted" style="font-size:12px;margin-top:18px">El evento original no se edita. Las revisiones se añaden al historial de incidencias.</p>`)}
function employees(c){c.innerHTML=head('El equipo que hace posible cada jornada.',`<button class="btn" id="add-employee">＋ Nuevo empleado</button>`)+`<section class="card"><div class="toolbar"><label class="sr-only" for="employee-query">Buscar empleados</label><input id="employee-query" type="search" class="input" placeholder="Buscar por nombre, número o puesto…"><label class="sr-only" for="employee-branch">Sucursal</label><select id="employee-branch" class="input"><option value="">Todas las sucursales</option>${MRH.state.branches.map(b=>`<option>${esc(b.name)}</option>`).join('')}</select><label class="sr-only" for="employee-status">Estado</label><select id="employee-status" class="input"><option value="">Todos los estados</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select></div><div id="employees-table"></div></section>`;const update=()=>{const q=c.querySelector('#employee-query').value.toLocaleLowerCase('es'),branch=c.querySelector('#employee-branch').value,status=c.querySelector('#employee-status').value;const es=MRH.state.employees.filter(e=>(e.name+' '+e.id+' '+e.job).toLocaleLowerCase('es').includes(q)&&(!branch||e.branch===branch)&&(!status||e.active===(status==='active')));c.querySelector('#employees-table').innerHTML=table(['Empleado','Sucursal','Jornada','Estado','Acciones'],es.map(e=>`<tr><td>${person(e.id)}</td><td>${esc(e.branch)}</td><td>${esc(e.shift)}</td><td>${pill(e.active?'Activo':'Inactivo')}</td><td><button class="btn secondary small" data-edit="${esc(e.id)}">Editar</button> <button class="btn ghost small" data-toggle="${esc(e.id)}">${e.active?'Desactivar':'Activar'}</button></td></tr>`).join(''));c.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>employeeForm(b.dataset.edit));c.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const e=MRH.employee(b.dataset.toggle);const m=modal(e.active?'Desactivar empleado':'Activar empleado',`<p>${esc(e.name)} ${e.active?'dejará de aparecer en el marcador de esta demo. Sus registros se conservarán.':'volverá a aparecer en el marcador de su sucursal.'}</p><div class="modal-actions"><button class="btn secondary" data-cancel>Cancelar</button><button class="btn" id="confirm-toggle">Confirmar</button></div>`);wireCancel(m);m.querySelector('#confirm-toggle').onclick=()=>{if(MRH.transaction(s=>{const x=s.employees.find(x=>x.id===e.id);x.active=!x.active})){MRH.audit('Estado de empleado',e.id+' · '+(!e.active?'Activo':'Inactivo'));closeModal();update();toast('Estado actualizado; historial conservado.')}}})};c.querySelectorAll('.toolbar input,.toolbar select').forEach(el=>el.addEventListener(el.tagName==='INPUT'?'input':'change',update));c.querySelector('#add-employee').onclick=()=>employeeForm();update()}
function employeeForm(id){const e=id?MRH.employee(id):{name:'',job:'',branch:'San José',shift:'Diurno'};const m=modal(id?'Editar empleado':'Nuevo empleado',`<p class="muted">Datos ficticios de la empresa demo. No ingreses información sensible.</p><form>${F('Nombre completo','name',e.name,'text','required maxlength="80"')}${F('Puesto / departamento','job',e.job,'text','required maxlength="80"')}<div class="grid2">${S('Sucursal','branch',MRH.state.branches.map(x=>x.name),e.branch)}${S('Jornada','shift',MRH.state.shifts.map(x=>x.name),e.shift)}</div><div class="notice">La demo utiliza el PIN fijo 123456. El producto final provisionará verificadores seguros, sin exponer el PIN al administrador.</div>${buttonsSave(id?'Guardar cambios':'Crear empleado')}</form>`);wireCancel(m);m.querySelector('form').onsubmit=ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target));data.name=data.name.trim();data.job=data.job.trim();if(!data.name||!data.job)return toast('Completa nombre y puesto.');const newId=id||'E'+String(Math.max(0,...MRH.state.employees.map(x=>Number(x.id.slice(1))))+1).padStart(3,'0');if(MRH.transaction(s=>{if(id)Object.assign(s.employees.find(x=>x.id===id),data);else s.employees.push({...data,id:newId,active:true})})){MRH.audit(id?'Editar empleado':'Alta de empleado',newId+' · '+data.name);closeModal();render();toast('Empleado guardado en la demostración.')}}}
function attendance(c){c.innerHTML=head('Hechos originales enviados por terminales. La web administrativa no genera marcaciones.')+`<div class="notice" style="margin-bottom:22px">Solo se listan eventos recibidos en la sincronización demo. Las colas locales pendientes permanecen en el marcador.</div><section class="card"><div class="toolbar"><input class="input" type="search" id="event-query" aria-label="Buscar empleado o terminal" placeholder="Buscar empleado o terminal…"><select id="event-status" class="input" aria-label="Estado"><option value="">Todos los estados</option><option>Recibida</option><option>Observada</option></select><button class="btn secondary" id="export-events">↓ Exportar CSV</button></div><div id="events-table"></div></section>`;let filtered=[];function update(){const q=c.querySelector('#event-query').value.toLocaleLowerCase('es'),status=c.querySelector('#event-status').value;filtered=MRH.state.events.filter(e=>e.status!=='Pendiente'&&(!status||e.status===status)&&((MRH.employee(e.employee)?.name||'')+' '+e.device).toLocaleLowerCase('es').includes(q)).reverse();c.querySelector('#events-table').innerHTML=eventsTable(filtered);wireEvents(c)};c.querySelector('#event-query').oninput=update;c.querySelector('#event-status').onchange=update;c.querySelector('#export-events').onclick=()=>exportEvents(filtered);update()}
function exportEvents(events){MRH.download('markarh-registros-demo.csv',MRH.csv([['UUID','Empleado','Sucursal','Fecha local CR','Hora local CR','Evento','Terminal','Estado','Alcance'],...events.map(e=>[e.id,MRH.employee(e.employee)?.name,MRH.employee(e.employee)?.branch,MRH.day(e.time),MRH.time(e.time),e.action,e.device,e.status,'Datos demo; no acredita asistencia'])]),'text/csv;charset=utf-8');MRH.audit('Exportar CSV',events.length+' eventos · Solo datos demo');toast('CSV descargado con los registros filtrados.')}
function issues(c){c.innerHTML=head('Revisa las excepciones sin sobrescribir los eventos originales.')+`<section class="card"><div class="toolbar"><select class="input" id="issue-status" aria-label="Estado de incidencia"><option value="">Todas las incidencias</option><option>Pendiente</option><option>Conciliada</option></select></div><div id="issues-table"></div></section>`;const update=()=>{const status=c.querySelector('#issue-status').value;c.querySelector('#issues-table').innerHTML=table(['Empleado','Incidencia','Estado',''],MRH.state.issues.filter(i=>!status||i.status===status).map(i=>`<tr><td>${person(i.employee)}</td><td>${esc(i.title)}<small style="display:block;margin-top:7px;max-width:370px;white-space:normal;line-height:1.6">${esc(i.detail)}</small></td><td>${pill(i.status)}</td><td><button class="btn secondary small" data-issue="${esc(i.id)}">${i.status==='Pendiente'?'Revisar':'Ver historial'} →</button></td></tr>`).join(''));wireIssues(c)};c.querySelector('#issue-status').onchange=update;update()}
function wireIssues(c){c.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>issueForm(b.dataset.issue));wireEvents(c)}
function issueForm(id){const i=MRH.state.issues.find(x=>x.id===id);if(i.status!=='Pendiente'){modal('Historial de conciliación',`${person(i.employee)}<p style="margin-top:25px">${esc(i.title)}</p><div class="notice">${esc(i.resolution)}<br>Motivo: ${esc(i.reason)}<br>Autor: Administración demo<br>Fecha: ${esc(i.resolvedAt?MRH.day(i.resolvedAt)+' '+MRH.time(i.resolvedAt):'No disponible')}</div><p class="muted" style="margin-top:20px">La evidencia original permanece sin modificaciones.</p>`);return}const m=modal('Revisar incidencia',`${person(i.employee)}<h3 style="margin-top:24px">${esc(i.title)}</h3><p class="muted">${esc(i.detail)}</p><form>${S('Resolución','resolution',['Justificada con respaldo','Solicitar corrección de horario','Confirmar registro observado'])}<div class="field"><label for="reason">Motivo y evidencia de la revisión</label><textarea id="reason" name="reason" required minlength="10" maxlength="700" placeholder="Explica la decisión (mínimo 10 caracteres)"></textarea></div><div class="notice">Se añadirá una revisión con autor y fecha. No se inventará una marcación original ni se recalcularán pagos.</div>${buttonsSave('Guardar revisión')}</form>`);wireCancel(m);m.querySelector('form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.reason.trim().length<10)return toast('Describe el motivo con al menos 10 caracteres.');if(MRH.transaction(s=>Object.assign(s.issues.find(x=>x.id===id),d,{status:'Conciliada',resolvedAt:new Date().toISOString()}))){MRH.audit('Conciliar incidencia',id+' · '+d.resolution+' · Motivo: '+d.reason);closeModal();shell();toast('Revisión guardada. La evidencia original se conserva.')}}}
function shifts(c){c.innerHTML=head('Horarios de referencia y descansos. Los cálculos laborales requieren validación.',`<button class="btn" id="add-shift">＋ Nuevo turno</button>`)+`<div class="notice warn" style="margin-bottom:23px">Reglas CR orientativas: diurna 8 h / 48 h, mixta 7 h / 42 h, nocturna 6 h / 36 h. No se aplica una liquidación legal ni un descuento automático en esta demo.</div><div class="grid3">${MRH.state.shifts.map(s=>`<article class="card shift-card"><div class="row between"><span class="pill blue">${esc(s.name)}</span><button class="btn ghost small" data-shift="${esc(s.id)}">Editar</button></div><div class="shift-time">${esc(s.start)} <span class="muted" style="font-size:17px">→</span> ${esc(s.end)}</div><p class="muted" style="font-size:11px">${esc(s.days)}${s.end<s.start?'<br>Finaliza al día siguiente':''}</p><div style="border-top:1px solid var(--line);padding-top:17px;font-size:11px;line-height:1.8"><span class="muted">Descanso</span><br>${esc(s.rest)}</div><small style="display:block;margin-top:20px">${MRH.state.employees.filter(e=>e.shift===s.name&&e.active).length} empleados activos asignados</small></article>`).join('')}</div>`;c.querySelector('#add-shift').onclick=()=>shiftForm();c.querySelectorAll('[data-shift]').forEach(b=>b.onclick=()=>shiftForm(b.dataset.shift))}
function shiftForm(id){const s=MRH.state.shifts.find(x=>x.id===id)||{name:'',start:'08:00',end:'17:00',rest:'Continuo remunerado · 30 min',days:'Lunes a viernes'};const m=modal(id?'Editar turno':'Nuevo turno',`<form>${F('Nombre del turno','name',s.name,'text','required maxlength="50"')}<div class="grid2">${F('Hora de inicio','start',s.start,'time','required')}${F('Hora de fin','end',s.end,'time','required')}</div>${S('Descanso','rest',['Continuo remunerado · 30 min','Discontinuo no remunerado · 60 min','Según contrato revisado'],s.rest)}${S('Días','days',['Lunes a viernes','Lunes a sábado','Rotativo según planificación'],s.days)}<div class="notice warn">Un fin anterior al inicio representa un turno que cruza medianoche. Este formulario no certifica cumplimiento laboral.</div>${buttonsSave()}</form>`);wireCancel(m);m.querySelector('form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();if(!d.name)return toast('Ingresa un nombre.');if(MRH.state.shifts.some(x=>x.id!==id&&x.name.toLowerCase()===d.name.toLowerCase()))return toast('Ya existe un turno con ese nombre.');if(d.start===d.end)return toast('El inicio y fin no pueden ser iguales.');if(MRH.transaction(st=>{if(id){Object.assign(st.shifts.find(x=>x.id===id),d);st.employees.filter(x=>x.shift===s.name).forEach(x=>x.shift=d.name)}else st.shifts.push({...d,id:crypto.randomUUID()})})){MRH.audit('Configurar turno',d.name+' · '+d.start+'–'+d.end);closeModal();render();toast('Turno guardado para la demostración.')}}}
function leaves(c){c.innerHTML=head('Solicitudes registradas por administración y decisiones con trazabilidad.',`<button class="btn" id="add-leave">＋ Registrar solicitud</button>`)+`<section class="card"><div class="card-head"><h3>Permisos y vacaciones</h3><span class="pill blue">${MRH.state.leaves.filter(x=>x.status==='Pendiente').length} pendientes</span></div>${table(['Empleado','Tipo','Período','Estado',''],MRH.state.leaves.map(l=>`<tr><td>${person(l.employee)}</td><td>${esc(l.type)}</td><td>${esc(l.start)} → ${esc(l.end)}</td><td>${pill(l.status)}</td><td><button class="btn secondary small" data-leave="${esc(l.id)}">Revisar →</button></td></tr>`).join(''))}</section><div class="notice" style="margin-top:22px">Los saldos de vacaciones y el devengo legal no se calculan en este prototipo. Una aprobación demo no descuenta días ni salarios.</div>`;c.querySelector('#add-leave').onclick=leaveForm;c.querySelectorAll('[data-leave]').forEach(b=>b.onclick=()=>reviewLeave(b.dataset.leave))}
function leaveForm(){const m=modal('Registrar solicitud',`<form><div class="field"><label for="leave-employee">Empleado</label><select id="leave-employee" name="employee">${MRH.state.employees.filter(x=>x.active).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div>${S('Tipo','type',['Vacaciones','Permiso con goce','Permiso sin goce','Incapacidad'])}<div class="grid2">${F('Desde','start',MRH.date,'date','required')}${F('Hasta','end',MRH.date,'date','required')}</div>${F('Motivo (ficticio)','reason','','text','required minlength="5" maxlength="250"')}${buttonsSave('Registrar solicitud')}</form>`);wireCancel(m);m.querySelector('form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.end<d.start)return toast('La fecha final debe ser igual o posterior al inicio.');if(MRH.transaction(s=>s.leaves.push({...d,id:crypto.randomUUID(),status:'Pendiente'}))){MRH.audit('Registrar solicitud',d.type+' · '+d.employee);closeModal();render();toast('Solicitud registrada.')}}}
function reviewLeave(id){const l=MRH.state.leaves.find(x=>x.id===id);const m=modal('Revisar solicitud',`${person(l.employee)}<h3 style="margin-top:24px">${esc(l.type)} · ${esc(l.start)} a ${esc(l.end)}</h3><p class="muted">${esc(l.reason)}</p>${l.status!=='Pendiente'?`<div class="notice">${esc(l.status)} · ${esc(l.decisionReason||'Sin motivo')}<br>${esc(l.decidedAt?MRH.day(l.decidedAt):'')}</div>`:`<form>${S('Decisión','status',['Aprobada','Rechazada'])}${F('Motivo de la decisión','decisionReason','','text','required minlength="5" maxlength="300"')}${buttonsSave('Guardar decisión')}</form>`}`);wireCancel(m);const f=m.querySelector('form');if(f)f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(MRH.transaction(s=>Object.assign(s.leaves.find(x=>x.id===id),d,{decidedAt:new Date().toISOString()}))){MRH.audit('Resolver solicitud',id+' · '+d.status+' · '+d.decisionReason);closeModal();render();toast('Decisión guardada con trazabilidad.')}}}
function reports(c){c.innerHTML=head('Exporta datos recibidos y deja constancia de los criterios de consulta.')+`<section class="card"><div class="card-head"><div><h3>Reporte de asistencia</h3><small>Consulta por período, empleado y sucursal.</small></div><span class="pill blue">Solo datos demo</span></div><form id="report-form"><div class="grid3"><div class="grid2">${F('Desde','from',MRH.date,'date','required')}${F('Hasta','to',MRH.date,'date','required')}</div><div class="field"><label for="report-employee">Empleado</label><select id="report-employee" name="employee"><option value="">Todos los empleados</option>${MRH.state.employees.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label for="report-branch">Sucursal</label><select id="report-branch" name="branch"><option value="">Todas las sucursales</option>${MRH.state.branches.map(b=>`<option>${esc(b.name)}</option>`).join('')}</select></div></div><div class="row wrap"><button class="btn" type="submit">Generar reporte</button><button class="btn secondary" type="button" id="report-csv" disabled>↓ Descargar CSV</button><button class="btn secondary" type="button" id="report-print" disabled>▤ Imprimir / Guardar PDF</button></div></form></section><div id="report-result" style="margin-top:22px"></div><div class="notice warn" style="margin-top:22px">No incluye eventos pendientes en terminales desconectadas. No se calculan remuneraciones, aguinaldo ni horas definitivas a partir de secuencias incompletas. Exportación XLSX pendiente; CSV abre en Excel.</div>`;let rows=[];c.querySelector('#report-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.to<d.from)return toast('Corrige el rango de fechas.');rows=MRH.state.events.filter(x=>{const date=new Date(x.time).toLocaleDateString('en-CA',{timeZone:'America/Costa_Rica'});return x.status!=='Pendiente'&&date>=d.from&&date<=d.to&&(!d.employee||x.employee===d.employee)&&(!d.branch||MRH.employee(x.employee)?.branch===d.branch)});c.querySelector('#report-result').innerHTML=`<section class="card"><div class="card-head"><div><h3>Resultados · ${rows.length} eventos</h3><small>${esc(d.from)} → ${esc(d.to)} · ${esc(d.branch||'Todas las sucursales')} · Evidencia demo</small></div><span class="pill warn">${rows.filter(x=>x.status==='Observada').length} observados</span></div>${eventsTable(rows,false)}</section>`;c.querySelector('#report-csv').disabled=false;c.querySelector('#report-print').disabled=false;MRH.audit('Consultar reporte',`${d.from} → ${d.to} · ${rows.length} eventos`)};c.querySelector('#report-csv').onclick=()=>exportEvents(rows);c.querySelector('#report-print').onclick=()=>{MRH.audit('Imprimir reporte',rows.length+' eventos · PDF mediante navegador');window.print()}}
function devices(c){c.innerHTML=head('Terminales autorizadas para la empresa. Las licencias y la red son simuladas.')+`<div class="grid2">${MRH.state.devices.map(d=>`<article class="card"><div class="card-head"><div class="row"><span class="icon">${d.platform==='Windows'?'▦':'▯'}</span><div><h3>${esc(d.name)}</h3><small>${esc(d.branch)} · ${esc(d.id)}</small></div></div>${pill(d.state)}</div><div class="grid2" style="font-size:12px;line-height:1.8"><div><small>Sistema</small><br>${esc(d.platform)}</div><div><small>Última recepción demo</small><br>${d.id==='SJ-01'&&MRH.state.lastSync?MRH.day(MRH.state.lastSync)+' '+MRH.time(MRH.state.lastSync):'No ejecutada'}</div><div><small>Seguridad</small><br>PIN de demostración</div><div><small>Modo</small><br>${MRH.state.settings.mode==='auto'?'Automático':'Explícito'}</div></div><div class="row between wrap" style="margin-top:24px;border-top:1px solid var(--line);padding-top:20px"><small>Configuración local de prueba</small><button class="btn ${d.state==='Revocado'?'secondary':'danger'} small" data-revoke="${esc(d.id)}">${d.state==='Revocado'?'Reactivar demo':'Revocar demo'}</button></div></article>`).join('')}</div><section class="card" style="margin-top:22px"><h3>Política del marcador de San José</h3><p class="muted" style="font-size:12px">Este ajuste se aplica al prototipo abierto en el mismo navegador. En producción se enviará al equipo mediante sincronización.</p><form id="device-policy">${S('Modo de marcación','mode',['Tipo explícito','Registro automático'],MRH.state.settings.mode==='auto'?'Registro automático':'Tipo explícito')}<div class="notice">Foto, token, lector de huella y aprovisionamiento seguro requieren implementación nativa. No se habilitan verificaciones ficticias.</div><button class="btn" style="margin-top:20px">Guardar política demo</button></form></section>`;c.querySelector('#device-policy').onsubmit=e=>{e.preventDefault();const mode=new FormData(e.target).get('mode')==='Registro automático'?'auto':'explicit';if(MRH.transaction(s=>s.settings.mode=mode)){MRH.audit('Política de terminal','SJ-01 · '+mode);render();toast('Política demo guardada.')}};c.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>{const d=MRH.state.devices.find(x=>x.id===b.dataset.revoke),state=d.state==='Revocado'?'Activo':'Revocado';const m=modal(state==='Revocado'?'Revocar terminal demo':'Reactivar terminal demo',`<p>Se cambiará el estado de ${esc(d.name)} a ${esc(state)}. Las marcaciones existentes permanecerán intactas.</p><div class="notice warn">Esta simulación solo afecta las pantallas de este navegador. No emite ni revoca credenciales reales.</div><div class="modal-actions"><button class="btn secondary" data-cancel>Cancelar</button><button class="btn" id="confirm-device">Confirmar</button></div>`);wireCancel(m);m.querySelector('#confirm-device').onclick=()=>{if(MRH.transaction(s=>s.devices.find(x=>x.id===d.id).state=state)){MRH.audit('Estado de dispositivo',d.id+' · '+state);closeModal();render();toast('Estado de terminal actualizado.')}}})}
function company(c){c.innerHTML=head('Los lugares y la configuración que conectan a tu equipo.')+`<div class="grid2"><section class="card"><h3>Datos de la empresa demo</h3><p class="muted" style="font-size:12px">Identidad visible en el panel y el marcador.</p><form id="company-form">${F('Nombre comercial','company',MRH.state.settings.company,'text','required maxlength="80"')}<div class="field"><label>Zona horaria</label><div class="notice">America/Costa_Rica · UTC−6</div></div><div class="notice">Datos fiscales, usuarios delegados y permisos de backend se definirán al implementar el producto.</div><button class="btn" style="margin-top:22px">Guardar datos demo</button></form></section><section class="card"><div class="card-head"><h3>Sucursales</h3><button class="btn secondary small" id="add-branch">＋ Agregar</button></div>${MRH.state.branches.map(b=>`<div class="device-row"><div><b>${esc(b.name)}</b><small>${esc(b.address)}</small><small>${MRH.state.employees.filter(e=>e.branch===b.name&&e.active).length} empleados activos · Costa Rica</small></div><span class="pill blue">${esc(b.id)}</span></div>`).join('')}</section></div>`;c.querySelector('#company-form').onsubmit=e=>{e.preventDefault();const value=new FormData(e.target).get('company').trim();if(!value)return toast('El nombre no puede estar vacío.');if(MRH.transaction(s=>s.settings.company=value)){MRH.audit('Editar empresa',value);shell();toast('Nombre actualizado.')}};c.querySelector('#add-branch').onclick=()=>{const m=modal('Agregar sucursal',`<form>${F('Nombre','name','','text','required maxlength="60"')}${F('Ubicación','address','','text','required maxlength="150"')}<div class="notice">Zona horaria: America/Costa_Rica.</div>${buttonsSave('Crear sucursal')}</form>`);wireCancel(m);m.querySelector('form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();if(!d.name)return toast('Ingresa un nombre.');if(MRH.state.branches.some(b=>b.name.toLowerCase()===d.name.toLowerCase()))return toast('Ya existe una sucursal con ese nombre.');if(MRH.transaction(s=>s.branches.push({...d,id:'S'+String(s.branches.length+1).padStart(2,'0'),timezone:'America/Costa_Rica'}))){MRH.audit('Crear sucursal',d.name);closeModal();render();toast('Sucursal agregada.')}}}}
function audit(c){c.innerHTML=head('Historial de acciones de la demostración. En producción será un registro protegido.',`<button class="btn secondary" id="export-audit">↓ Exportar bitácora</button>`)+`<div class="notice" style="margin-bottom:22px">Esta bitácora local es ilustrativa y editable desde el navegador. No constituye auditoría inmutable ni control de acceso real.</div><section class="card">${table(['Fecha local CR','Responsable','Acción','Detalle'],MRH.state.audit.map(a=>`<tr><td>${MRH.day(a.time)}<small style="display:block;margin-top:6px">${MRH.time(a.time)}</small></td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td style="white-space:normal;min-width:200px;line-height:1.7">${esc(a.detail)}</td></tr>`).join(''))}</section>`;c.querySelector('#export-audit').onclick=()=>MRH.download('markarh-bitacora-demo.csv',MRH.csv([['Fecha ISO','Actor','Acción','Detalle'],...MRH.state.audit.map(a=>[a.time,a.actor,a.action,a.detail])]),'text/csv;charset=utf-8')}
function notifications(){const issues=role==='master'?[]:MRH.state.issues.filter(i=>i.status==='Pendiente');modal('Tu centro de notificaciones',role==='master'?`<div class="notice">${MRH.state.companies.filter(c=>c.state==='En gracia').length} empresa(s) en período de gracia.</div><p class="muted" style="margin-top:20px">El estado del hosting y las alertas de infraestructura requieren una conexión real al backend.</p>`:issues.map(i=>`<div class="alert-row"><div><b>${esc(i.title)}</b><small>${esc(MRH.employee(i.employee)?.name)}</small></div>${pill('Pendiente')}</div>`).join('')||'<div class="empty">No hay notificaciones pendientes.</div>')}
function globalDashboard(c){const s=MRH.state;c.innerHTML=head('La operación de MarkaRH, desde una sola vista.',`<a class="btn" href="#empresas">Gestionar empresas →</a>`)+`<div class="notice">Vista Maestro demo · El producto final requerirá MFA y auditoría de accesos. No se muestran datos laborales de empresas ajenas.</div><div class="stats">${stat('Empresas afiliadas',s.companies.length,'Catálogo ficticio de demostración','▥')}${stat('Licencias activas',s.companies.filter(c=>c.state==='Activa').length,'Estados comerciales ilustrativos','◎')}${stat('En período de gracia',s.companies.filter(c=>c.state==='En gracia').length,'Sin eliminación de registros','◷',true)}${stat('Consultas recibidas',s.contacts.length,'Solicitudes locales de la web pública','◇')}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><h3>Empresas en la plataforma</h3><a href="#empresas" style="font-size:11px;color:var(--blue)">Ver catálogo →</a></div>${table(['Empresa','Plan','Estado'],s.companies.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.plan)}</td><td>${pill(x.state)}</td></tr>`).join(''))}</section><section class="card"><h3>Tu sitio, tu identidad.</h3><p class="muted" style="font-size:12px">Actualiza el mensaje de la web oficial y revisa cómo se verá antes de publicarlo en esta demostración.</p><div style="border:1px solid var(--line);padding:20px;border-radius:10px;margin:20px 0"><img src="assets/logo.svg" class="brand" style="width:160px" alt="MarkaRH"><small style="display:block;margin-top:15px">${s.cms.published?'Última publicación demo: '+MRH.day(s.cms.published):'Contenido inicial · Sin publicaciones demo'}</small></div><a href="#sitio" class="btn secondary">Abrir editor web →</a></section></div><section class="card"><h3>Estado de la plataforma</h3><div class="grid3" style="margin-top:20px">${['API y sincronización','Almacenamiento central','Instaladores firmados'].map(x=>`<div class="notice"><b>${x}</b><br>Pendiente de implementación.<br>No hay servicio conectado.</div>`).join('')}</div></section>`}
function companies(c){c.innerHTML=head('Empresas, planes y estados comerciales de la plataforma demo.',`<button class="btn" id="add-company">＋ Nueva empresa</button>`)+`<section class="card"><div class="toolbar"><input id="company-query" type="search" class="input" placeholder="Buscar empresa…" aria-label="Buscar empresa"></div><div id="companies-table"></div></section><div class="notice" style="margin-top:22px">No se procesan pagos, no se emiten credenciales ni se accede al personal de estas empresas. Los límites comerciales se definirán en contratos y backend.</div>`;const update=()=>{const q=c.querySelector('#company-query').value.toLocaleLowerCase('es');c.querySelector('#companies-table').innerHTML=table(['Empresa','Plan','Personal / terminales','Licencia',''],MRH.state.companies.filter(x=>x.name.toLocaleLowerCase('es').includes(q)).map(x=>`<tr><td><b>${esc(x.name)}</b><small style="display:block;margin-top:6px">${esc(x.id)}</small></td><td>${esc(x.plan)}</td><td>${x.employees} empleados · ${x.devices} terminales</td><td>${pill(x.state)}</td><td><button class="btn secondary small" data-company="${esc(x.id)}">Gestionar</button></td></tr>`).join(''));c.querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>companyForm(b.dataset.company))};c.querySelector('#company-query').oninput=update;c.querySelector('#add-company').onclick=()=>companyForm();update()}
function companyForm(id){const x=MRH.state.companies.find(c=>c.id===id)||{name:'',plan:'Esencial',state:'Activa',employees:0,devices:0};const m=modal(id?'Gestionar licencia demo':'Nueva empresa demo',`<form>${F('Nombre comercial','name',x.name,'text','required maxlength="100"')}${S('Plan','plan',['Esencial','Profesional','Empresarial'],x.plan)}${S('Estado comercial','state',['Activa','En gracia','Suspendida'],x.state)}<div class="notice warn">Cambiar la licencia no elimina datos. El estado es ilustrativo y no implementa facturación ni credenciales.</div>${buttonsSave()}</form>`);wireCancel(m);m.querySelector('form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();if(!d.name)return toast('Ingresa el nombre de la empresa.');if(MRH.transaction(s=>{if(id)Object.assign(s.companies.find(c=>c.id===id),d);else s.companies.push({...d,id:'C-'+crypto.randomUUID().slice(0,6),employees:0,devices:0})})){MRH.audit('Gestionar empresa',d.name+' · '+d.plan+' · '+d.state);closeModal();render();toast('Empresa guardada en el catálogo demo.')}}}
function cms(c){const draft=MRH.state.cmsDraft||MRH.state.cms;c.innerHTML=head('Edita el mensaje principal y previsualiza antes de publicar en la demo.',`<a class="btn secondary" href="index.html" target="_blank" rel="noopener">Ver sitio →</a>`)+`<div class="grid2"><section class="card"><div class="card-head"><h3>Contenido de inicio</h3><span class="pill blue">Borrador</span></div><form id="cms-form">${F('Título principal','title',draft.title,'text','required maxlength="100"')}<div class="field"><label for="cms-description">Descripción</label><textarea name="description" id="cms-description" required maxlength="280">${esc(draft.description)}</textarea></div>${F('Color de acento','accent',draft.accent,'color')}<div class="notice">Solo texto y color. No admite HTML ni scripts. Guardar un borrador no cambia el sitio hasta publicarlo en la demo.</div><div class="row wrap" style="margin-top:22px"><button class="btn secondary" type="submit">Guardar borrador</button><button class="btn" type="button" id="publish-cms">Publicar demo →</button></div><p id="cms-status" class="muted" style="font-size:11px;margin:17px 0 0">${MRH.state.cmsDraft?'Hay un borrador guardado.':'Sin cambios pendientes guardados.'}</p></form></section><section class="card"><div class="card-head"><h3>Vista previa</h3><span class="pill gray">No publicado</span></div><div class="content-editor-preview"><span class="pill" style="background:#1b405b;color:#90d7cd">MARKARH · COSTA RICA</span><h2 id="preview-title"></h2><p id="preview-description"></p><span class="btn" id="preview-cta">Conversemos →</span></div><small style="display:block;margin-top:20px;font-size:11px;line-height:1.8">Publicar aquí actualiza únicamente el sitio HTML en este navegador. No sube contenido a internet ni publica el entorno.</small></section></div>`;const f=c.querySelector('#cms-form');const get=()=>Object.fromEntries(new FormData(f));function preview(){const d=get();c.querySelector('#preview-title').textContent=d.title;c.querySelector('#preview-description').textContent=d.description;c.querySelector('#preview-cta').style.backgroundColor=d.accent}f.oninput=preview;preview();f.onsubmit=e=>{e.preventDefault();const d=get();if(!d.title.trim()||!d.description.trim())return toast('Completa título y descripción.');if(MRH.transaction(s=>s.cmsDraft=d)){MRH.audit('Guardar borrador web','Sección de inicio');c.querySelector('#cms-status').textContent='Borrador guardado. El sitio publicado no ha cambiado.';toast('Borrador guardado.')}};c.querySelector('#publish-cms').onclick=()=>{if(!f.reportValidity())return;const d=get();if(!d.title.trim()||!d.description.trim())return toast('Completa título y descripción.');const m=modal('Publicar cambios en la demo',`<p>Se actualizará el mensaje de la web pública en este navegador. No se publicará ningún sitio en internet.</p><div class="notice">${esc(d.title)}</div><div class="modal-actions"><button class="btn secondary" data-cancel>Cancelar</button><button class="btn" id="confirm-publish">Publicar demo</button></div>`);wireCancel(m);m.querySelector('#confirm-publish').onclick=()=>{if(MRH.transaction(s=>{s.cms={...d,published:new Date().toISOString()};s.cmsDraft=null})){MRH.audit('Publicar web demo','Título y color de inicio');closeModal();render();toast('Contenido publicado en la web demo de este navegador.')}}}}
function contacts(c){c.innerHTML=head('Consultas guardadas desde el sitio público de demostración.')+`<section class="card">${table(['Fecha local CR','Contacto','Empresa','Plan'],MRH.state.contacts.map(x=>`<tr><td>${MRH.day(x.time)}</td><td><b>${esc(x.name)}</b><small style="display:block;margin-top:6px">${esc(x.email)}</small></td><td>${esc(x.company)}</td><td>${pill(x.plan)}</td></tr>`).join(''))}</section><div class="notice" style="margin-top:22px">Estas solicitudes se guardan solo localmente. No se envían correos ni mensajes a terceros.</div>`}
function overtime(c){const rows=MRH.state.overtime||[];c.innerHTML=head('Solicitudes y autorizaciones separadas de las horas efectivamente trabajadas.',`<button class="btn" id="add-overtime">＋ Registrar solicitud</button>`)+`<div class="notice warn" style="margin-bottom:22px">Aprobar una solicitud no certifica tiempo trabajado ni determina pago. Una autorización empresarial no elimina obligaciones legales por trabajo efectivamente realizado.</div><section class="card">${table(['Empleado','Fecha','Horas solicitadas','Autorización','Trabajo / pago',''],rows.map(x=>`<tr><td>${person(x.employee)}</td><td>${esc(x.date)}</td><td>${esc(x.hours)} h</td><td>${pill(x.status)}</td><td><span class="muted">Pendiente de conciliar</span></td><td><button class="btn secondary small" data-overtime="${esc(x.id)}">Revisar</button></td></tr>`).join(''))}</section>`;c.querySelector('#add-overtime').onclick=()=>{const m=modal('Solicitud de horas extra',`<form><div class="field"><label for="extra-employee">Empleado</label><select name="employee" id="extra-employee">${MRH.state.employees.filter(x=>x.active).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div>${F('Fecha','date',MRH.date,'date','required')}${F('Horas solicitadas','hours','1','number','required min="0.25" max="12" step="0.25"')}${F('Justificación','reason','','text','required minlength="5" maxlength="250"')}${buttonsSave('Registrar solicitud')}</form>`);wireCancel(m);m.querySelector('form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(MRH.transaction(s=>{s.overtime??=[];s.overtime.push({...d,id:crypto.randomUUID(),status:'Pendiente'})})){MRH.audit('Solicitar horas extra',d.employee+' · '+d.hours+' h solicitadas');closeModal();render();toast('Solicitud registrada, sin horas ni pagos calculados.')}}};c.querySelectorAll('[data-overtime]').forEach(b=>b.onclick=()=>{const x=rows.find(x=>x.id===b.dataset.overtime);const m=modal('Revisión de horas extra',`${person(x.employee)}<p style="margin-top:20px">${esc(x.hours)} h solicitadas · ${esc(x.date)}</p><p class="muted">${esc(x.reason)}</p>${x.status==='Pendiente'?`<form>${S('Decisión','status',['Aprobada','Rechazada'])}${F('Motivo de la decisión','reviewReason','','text','required minlength="5" maxlength="250"')}${buttonsSave('Guardar decisión')}</form>`:`<div class="notice">${esc(x.status)} · ${esc(x.reviewReason)}</div>`}`);wireCancel(m);const f=m.querySelector('form');if(f)f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(MRH.transaction(s=>Object.assign(s.overtime.find(y=>y.id===x.id),d,{reviewedAt:new Date().toISOString()}))){MRH.audit('Revisar horas extra',x.id+' · '+d.status+' · '+d.reviewReason);closeModal();render();toast('Decisión guardada. Trabajo efectivo aún sin conciliar.')}}})}
function prepay(c){const es=MRH.state.employees.filter(x=>x.active);c.innerHTML=head('Consolidación preliminar para revisión administrativa.',`<button class="btn secondary" id="prepay-csv">↓ Exportar pendientes CSV</button>`)+`<div class="notice warn" style="margin-bottom:22px">Cálculo incompleto: faltan historial salarial, contratos validados y jornadas conciliadas. No se estiman importes legales, aguinaldo ni deducciones.</div><section class="card"><div class="card-head"><div><h3>Preparación de preplanilla</h3><small>Todos los registros recibidos de esta demo; sin liquidación de períodos.</small></div><span class="pill warn">No liquidable</span></div>${table(['Empleado','Registros recibidos','Horas ordinarias','Extras trabajadas','Importe','Estado'],es.map(e=>`<tr><td>${person(e.id)}</td><td>${MRH.state.events.filter(x=>x.employee===e.id&&x.status!=='Pendiente').length}</td><td>Por conciliar</td><td>No determinadas</td><td>—</td><td>${pill('Pendiente')}</td></tr>`).join(''))}</section><section class="card" style="margin-top:22px"><h3>Antes de calcular</h3><div class="grid3" style="margin-top:20px"><div class="notice">01 · Revisar eventos originales e incidencias por sucursal.</div><div class="notice">02 · Validar contratos, remuneraciones y reglas laborales versionadas.</div><div class="notice">03 · Aprobar la conciliación y revisar la propuesta de pago.</div></div></section>`;c.querySelector('#prepay-csv').onclick=()=>{MRH.download('markarh-preplanilla-incompleta-demo.csv',MRH.csv([['Empleado','Registros recibidos','Horas','Importe','Estado'],...es.map(e=>[e.name,MRH.state.events.filter(x=>x.employee===e.id&&x.status!=='Pendiente').length,'Por conciliar','No calculado','Cálculo incompleto - datos demo'])]),'text/csv;charset=utf-8');MRH.audit('Exportar preplanilla','Datos incompletos; sin importes calculados');toast('Pendientes exportados. No se generó una planilla de pago.')}}
window.addEventListener('hashchange',()=>{if(!role)return;const next=location.hash.slice(1);if(next===view)return;view=next;shell()});window.addEventListener('mrh-update',()=>{if(role&&!document.querySelector('.modal-backdrop'))render()});if(role&& !['company','master'].includes(role)){role=null;sessionStorage.removeItem('mrh-role')}shell();
